import math
def control(obs):
    m=obs.get('local_map',{})
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    def interp(points,x):
        p=sorted((float(a),float(b)) for a,b in points)
        for i in range(len(p)-1):
            if p[i][0]<=x<=p[i+1][0] and p[i+1][0]-p[i][0]>0.01:
                f=(x-p[i][0])/(p[i+1][0]-p[i][0])
                return p[i][1]*(1-f)+p[i+1][1]*f
        return None
    centres=[]
    for x in (2.0,4.0,6.0,8.0):
        l=interp(left,x); r=interp(right,x)
        if l is not None and r is not None: centres.append((x,(l+r)/2))
    target=0.0
    if centres:
        x,y=centres[-1]
        target=max(-18.0,min(18.0,math.degrees(math.atan2(y,x))*1.4))
    hitch=obs.get('hitch_deg',0.0)
    steer=max(-35.0,min(35.0,2.0*(hitch-target)))
    return steer,-0.8,180

