def control(obs):
    m=obs.get('local_map',{})
    def interp(pts,x):
        p=sorted((a,b) for a,b in pts)
        for i in range(len(p)-1):
            if p[i][0]<=x<=p[i+1][0]:
                a,b=p[i]; c,d=p[i+1]; return b+(d-b)*(x-a)/(c-a)
        return None
    l=m.get('left_rail',[]); r=m.get('right_rail',[])
    cs=[]
    for x in (3,6,9,12,15):
        a=interp(l,x); b=interp(r,x)
        if a is not None and b is not None: cs.append((x,(a+b)/2))
    if cs:
        x,y=cs[-1]; desired=max(-18,min(18,math.degrees(math.atan2(y,max(x,1)))*1.1))
    else: desired=0
    hitch=obs.get('hitch_deg',0)
    steer=max(-35,min(35,1.8*(hitch-desired)))
    return steer,-0.9,180

